import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.hwbV7reR.js";const k=JSON.parse('{"title":"Панель оркестратора","description":"","frontmatter":{},"headers":[],"relativePath":"panel.md","filePath":"panel.md","lastUpdated":1791695486000}'),d={name:"panel.md"};function n(o,s,p,h,l,c){return i(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="панель-оркестратора" tabindex="-1">Панель оркестратора <a class="header-anchor" href="#панель-оркестратора" aria-label="Permalink to &quot;Панель оркестратора&quot;">​</a></h1><p>Самостоятельный интерфейс оператора: серверы, технические назначения, незавершённые операции и последние события с длительностью этапов. Не зависит от кабинета Undercore, в режиме просмотра не опрашивает VPN-узлы и не меняет их состояние. Управление включается отдельно параметром <code>--manage</code> и использует общий с CLI слой команд.</p><h2 id="запуск" tabindex="-1">Запуск <a class="header-anchor" href="#запуск" aria-label="Permalink to &quot;Запуск&quot;">​</a></h2><p>Оркестратор должен уже создать журнал актуальной версии. Запускайте панель от того же сервисного пользователя с доступом к каталогу состояния. Создайте отдельный случайный ключ; каталог для него должен быть закрыт от других пользователей. Пример для стандартной установки (от пользователя, владеющего каталогом):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PY&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">import os</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">import secrets</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">path = &#39;/etc/vpn-orchestrator/panel.token&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">with os.fdopen(fd, &#39;w&#39;) as output:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    output.write(secrets.token_urlsafe(48) + &#39;\\n&#39;)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PY</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/vpn-orchestrator/settings.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --token-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/vpn-orchestrator/panel.token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8793</span></span></code></pre></div><p>Команда создания не перезаписывает существующий ключ. Команда панели работает на переднем плане; Ctrl+C останавливает только панель. Системный сервис автоматически не устанавливается. Порт разрешён в диапазоне 1024–65535, адрес всегда <code>127.0.0.1</code>.</p><p>Откройте <code>http://127.0.0.1:8793/</code> и введите содержимое файла ключа. Для удалённого сервера сначала установите SSH-туннель с одинаковым локальным и удалённым портом:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8793:127.0.0.1:8793</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> operator@your-server</span></span></code></pre></div><p><code>localhost</code>, произвольные Host и внешний reverse proxy не поддерживаются: используйте именно <code>127.0.0.1</code> и настроенный порт. Не открывайте порт в интернет. Ключ не передаётся в URL, аргументах запуска или localStorage. Не используйте backend-токен: совпадение блокирует запуск. Старый <code>admin_token_file</code> игнорируется.</p><p>Сессия действует один час, хранится только в памяти панели и исчезает при её перезапуске. «Выйти» отзывает текущую сессию. Для смены ключа замените его файл с правами 0600 и перезапустите панель. Файл ключа панели не включён в стандартный backup: после восстановления можно создать новый; VPN-идентичности от него не зависят.</p><h2 id="что-означают-данные" tabindex="-1">Что означают данные <a class="header-anchor" href="#что-означают-данные" aria-label="Permalink to &quot;Что означают данные&quot;">​</a></h2><ul><li><strong>Серверы:</strong> регион, протокол, режим новых выдач, число назначений и лимит, последнее сохранённое состояние разрешения на управление узлом (lease).</li><li><strong>Подключения:</strong> технический ID, выбранный сервер, ревизия, завершённость выдачи или переключения, запрет доступа и результат последней операции.</li><li><strong>События:</strong> этап, действие, причина, длительность и request_id для сопоставления с журналами. Длительности вложенных этапов нельзя складывать.</li></ul><p>Назначение сервера не означает, что пользователь сейчас подключён. Даже подтверждённое разрешение узла не доказывает доступность интернета у клиента. Панель не заменяет клиентскую проверку туннеля или внешний мониторинг.</p><p>Сводка SQLite согласована в пределах одного снимка; события читаются отдельно. Таблицы серверов и назначений имеют страницы по 50 строк. Обновление выполняется раз в 15 секунд, пока страница видима, и вручную кнопкой «Обновить». Если запрос не удался, старые данные явно помечаются как устаревшие.</p><p>События поступают от обновлённых процессов API/worker через <code>events.jsonl</code> и <code>events.previous.jsonl</code> в каталоге состояния: каждый не больше 256 КиБ, ответ содержит не больше 100 последних событий. Файлы имеют права 0600. События могут теряться при конкуренции или ошибке диска; это ограниченная диагностика, не аудит. До появления первого события сводка базы работает независимо. Журнал событий не входит в backup SQLite. В нём нет ключей, VPN-документов и произвольного текста ошибок агентов.</p><h2 id="отдельныи-http-api" tabindex="-1">Отдельный HTTP API <a class="header-anchor" href="#отдельныи-http-api" aria-label="Permalink to &quot;Отдельный HTTP API&quot;">​</a></h2><p>Этот API доступен только в процессе панели. Без <code>--manage</code> доступны только маршруты просмотра. Авторизация: сессионная cookie после входа или <code>Authorization: Bearer &lt;panel-key&gt;</code> для чтения. Backend-ключ не подходит. Проверка Host и источника запроса применяется и к API. CORS не включён.</p><table tabindex="0"><thead><tr><th>Метод и путь</th><th>Назначение</th></tr></thead><tbody><tr><td><code>POST /session</code></td><td>Вход: JSON с единственным полем <code>token</code>; выдаёт cookie</td></tr><tr><td><code>GET /admin/v1/overview</code></td><td>Сводка; параметры <code>node_offset</code>, <code>connection_offset</code> от 0 до 1 000 000</td></tr><tr><td><code>POST /admin/v1/logout</code></td><td>Отзыв текущей браузерной сессии</td></tr></tbody></table><p>POST требует точного заголовка <code>Origin: http://127.0.0.1:8793</code> (или выбранного порта). Вход ограничен 20 попытками за минуту на процесс; тело — до 1024 байт.</p><p>Ответ обзора описан моделью <code>PanelOverview</code> в <code>orchestrator/domain/panel.py</code>: <code>generated_at</code>, <code>nodes_total</code>, <code>connections_total</code>, <code>pending_creates</code>, <code>pending_switches</code>, <code>denied</code>, оба offset, <code>page_size</code>, <code>nodes</code>, <code>connections</code>, <code>events</code>, <code>events_available</code>. Ключи туннелей, конфигурации и адреса API узлов не входят в проекцию ответа.</p><p>Ошибки: 401 — нет действующей авторизации; 403 — недопустимый Host/Origin; 413 — слишком большое тело входа; 422 — неверные параметры страницы; 429 — лимит входов (<code>Retry-After: 60</code>); 503 — журнал недоступен, повреждён или имеет неподдерживаемую версию. Подробности внутренних исключений в ответ не передаются. Без <code>--manage</code> изменяющие маршруты отсутствуют. Экспорт конфигураций панель не предоставляет.</p><h2 id="управление" tabindex="-1">Управление <a class="header-anchor" href="#управление" aria-label="Permalink to &quot;Управление&quot;">​</a></h2><p>Для доверенного оператора запустите отдельный процесс с явным разрешением команд:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/vpn-orchestrator/settings.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --token-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/vpn-orchestrator/panel.token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manage</span></span></code></pre></div><p>Ключ этой панели теперь разрешает изменения. Backend-ключ по-прежнему не подходит. Режим не меняется из браузера. Прежняя команда без <code>--manage</code> остаётся только для чтения.</p><p>Доступны добавление <strong>уже установленного</strong> Amnezia-агента, изменение режима и лимита узла, отзыв доступа подключения, политики и журнал действий. Новый узел добавляется в режим <code>draining</code>; оператор явно разрешает новые выдачи после проверки. Это не установка VPN по SSH. Включение leases необратимо и требует их поддержки агентом.</p><p><code>draining</code> прекращает новые назначения; <code>disabled</code> запрещает выдачу параметров, но сами по себе эти режимы не удаляют peer. Для отзыва используется существующий жизненный цикл <code>disable</code> с сохранением запрета и обработкой незавершённых переключений. Ответ <code>disable_requested</code> не обещает мгновенный разрыв туннеля при недоступном узле.</p><h3 id="контракт-команд" tabindex="-1">Контракт команд <a class="header-anchor" href="#контракт-команд" aria-label="Permalink to &quot;Контракт команд&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Метод</th><th>Путь</th><th>Результат</th></tr></thead><tbody><tr><td>GET</td><td><code>/admin/v1/capabilities</code></td><td><code>management</code>: включены ли команды</td></tr><tr><td>GET</td><td><code>/admin/v1/policy</code></td><td>Полная политика, её revision, <code>activation: restart_required</code></td></tr><tr><td>GET</td><td><code>/admin/v1/audit</code></td><td>Последние 100 записей долговечного аудита</td></tr><tr><td>POST</td><td><code>/admin/v1/commands</code></td><td>Выполнение одной команды; тело до 16 КиБ</td></tr></tbody></table><p>Последние три маршрута существуют только с <code>--manage</code>. Авторизация и проверка Origin такие же, как у остального API панели. Тело команды:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;operation_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;operator-change-001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node.mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node-nl-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;expected_revision&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;draining&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;capacity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>operation_id</code> и <code>target</code>: 1–80 символов <code>[A-Za-z0-9_-]</code>. Оболочка проверяется моделью <code>domain/administration.py</code>; лишние поля запрещены.</p><table tabindex="0"><thead><tr><th>action</th><th>target</th><th>data</th></tr></thead><tbody><tr><td><code>node.save</code></td><td>ID узла</td><td>NodeSettings без <code>api_key_file</code>, с <code>expected_revision</code> и необязательным <code>api_key</code>; для нового узла revision=0 и ключ обязателен</td></tr><tr><td><code>node.mode</code></td><td>ID узла</td><td>Текущая <code>expected_revision</code>, <code>mode</code>, <code>capacity</code></td></tr><tr><td><code>node.probe</code></td><td>ID узла</td><td>Пустой объект; проверка идентичности агента</td></tr><tr><td><code>node.restore</code></td><td>ID узла</td><td>Пустой объект; восстановление управления по существующим правилам leases</td></tr><tr><td><code>connection.disable</code></td><td>connection_id</td><td>Пустой объект; операторский отзыв без изменения подписки</td></tr><tr><td><code>policy.set</code></td><td><code>runtime</code></td><td><code>expected_revision</code> из GET policy и полный объект <code>policy</code></td></tr></tbody></table><p>Идентичный повтор завершённой команды возвращает сохранённый результат. Другое содержимое с тем же ID даёт 409 <code>operator_operation_conflict</code>. Незавершённая или неудачная команда с тем же ID даёт 409 <code>operator_review_required</code>: сначала проверьте состояние узла, затем при необходимости отправьте новую осознанную команду. Панель не повторяет изменения автоматически. Таймаут не означает отсутствие изменения.</p><p>Устаревшая revision узла/настроек даёт <code>node_revision_conflict</code> или <code>policy_revision_conflict</code>; некорректная политика — <code>invalid_policy</code> (422). Внутренняя ошибка команды возвращает 503 <code>operator_review_required</code>, без текста исключения или входного тела. Существующие ошибки жизненного цикла сохраняются.</p><h3 id="cli-и-настроики" tabindex="-1">CLI и настройки <a class="header-anchor" href="#cli-и-настроики" aria-label="Permalink to &quot;CLI и настройки&quot;">​</a></h3><p>Та же команда выполняется из приватного JSON-файла (права 0600):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> operator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> execute</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /secure/change.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> operator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> policy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> operator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span></span></code></pre></div><p>Прежние <code>add/update/check/restore server</code> и <code>node save/probe/restore</code> также используют этот слой и аудит. <code>connection ...</code> остаётся клиентом backend API с прежним контрактом; для операторского отзыва с аудитом используйте <code>operator execute</code>.</p><p>Политики валидируются теми же моделями RuntimePolicy. Settings-файл должен иметь права 0600, сервисный пользователь — право атомарной замены файла в его каталоге. Другие поля settings.json сохраняются. Перед изменением сравнивается хеш полного файла, после записи выполняются fsync и атомарная замена. Команды CLI/GUI сериализованы общей блокировкой; ручное редактирование файла в это время не поддерживается.</p><p>Запущенные API/worker сохраняют прежние политики; новые процессы читают новые значения. После изменения выполните контролируемый <code>undercore-orchestrator restart</code>. Панель не перезапускает службы и не меняет политику внутри незавершённой операции.</p><h3 id="журнал-деиствии" tabindex="-1">Журнал действий <a class="header-anchor" href="#журнал-деиствии" aria-label="Permalink to &quot;Журнал действий&quot;">​</a></h3><p><code>operator.sqlite3</code> (0600, отдельная схема 1) хранит ID операции, канал cli/panel, тип команды, target, время, outcome и безопасный результат. Входные тела, ключи и тексты исключений не сохраняются; для проверки повтора хранится только SHA256 команды.</p><p>До побочного действия синхронно фиксируется намерение. Недоступность аудита запрещает операцию. <code>started</code> после аварии означает неизвестный результат; <code>failed</code> тоже не доказывает отсутствие удалённого эффекта. Журнал не переигрывается автоматически и не является защитой от администратора с правом изменения файлов. Общий ключ не даёт персональной атрибуции. Автоматической очистки истории нет: контролируйте размер диска; при его заполнении команды прекращаются. В API возвращается только 100 последних записей, полная история сохраняется в резервных копиях.</p><p>Backup включает отдельный согласованный снимок аудита; он и снимок VPN-журнала не образуют общую транзакцию. После восстановления по-прежнему обязательна сверка узлов.</p>`,45)])])}const g=e(d,[["render",n]]);export{k as __pageData,g as default};
